ALTER TABLE "app"."books" DROP CONSTRAINT "books_author_fkey"
DROP INDEX IF EXISTS "app"."books_author_idx"
ALTER TABLE "app"."authors" DROP COLUMN "homepage"
DROP TABLE "app"."attachments"
ALTER TABLE "app"."books" ALTER COLUMN "price" TYPE numeric(12,2) USING "price"::numeric(12,2)
ALTER TABLE "app"."books" ALTER COLUMN "title" TYPE character varying(300) USING "title"::character varying(300)
CREATE TABLE "app"."reviews" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "book_id" bigint NOT NULL
)
ALTER TABLE "app"."authors" ADD COLUMN "bio" text
ALTER TABLE "app"."books" ADD COLUMN "isbn" character varying(20)
ALTER TABLE "app"."books" ADD CONSTRAINT "books_price_check" CHECK (price >= (0))
ALTER TABLE "app"."reviews" ADD CONSTRAINT "reviews_pkey" PRIMARY KEY (id)
CREATE UNIQUE INDEX authors_name_key ON app.authors USING btree (name)
CREATE INDEX books_author_idx ON app.books USING btree (author_id, title)
ALTER TABLE "app"."reviews" ADD CONSTRAINT "reviews_book_fkey" FOREIGN KEY (book_id) REFERENCES app.books(id) ON DELETE CASCADE

